    const L = laneMaxLen(l);
    if (typeof Z.axisPos[l] !== "number") Z.axisPos[l] = ovAl() === "left" ? x : ovAl() === "right" ? x + 2 * L : x + L;
    Z.axisPos[l] = Math.max(ovMinA(L), Math.round(Z.axisPos[l]));
