  L.className = "ov-mode";
  const A = ovAxes(), H = ovHeight();
  let maxEnd = 0;
  for (let l = 0; l < N; l++) { const Lm = laneMaxLen(l); maxEnd = Math.max(maxEnd, ovStart(A[l], Lm) + 2 * Lm, A[l] + 2); }
  const W = (maxEnd + 6) / 2 + "ch";
