  [1, 0.8, 0.6, 0.42].forEach((a, b) => { fill(P[4 + b * 2], c1, 1); fill(P[4 + b * 2], "#ffd166", a); fill(P[5 + b * 2], c0, 1); fill(P[5 + b * 2], "#b8860b", a); });   // остывание: золото поверх цвета бита
